import os
import requests

def timestamped_transcript(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.getenv("ASSEMBLYAI_API_KEY")
    if not api_key:
        raise ValueError("Missing AssemblyAI API key")
    transcription_url = config.get("transcription_url", "https://api.assemblyai.com/v2/transcript")
    headers = {
        "authorization": api_key,
        "content-type": "application/json",
    }
    create_body = {
        "audio_url": payload["audio_url"],
        "word_boost": payload.get("word_boost"),
        "language_code": payload.get("language_code"),
        "punctuate": payload.get("punctuate", True),
        "format_text": payload.get("format_text", True),
        "speaker_labels": payload.get("speaker_labels", False),
        "auto_chapters": payload.get("auto_chapters", False),
        "auto_highlights": payload.get("auto_highlights", False),
        "disfluencies": payload.get("disfluencies", False),
        "language_detection": payload.get("language_detection", False),
        "sentiment_analysis": payload.get("sentiment_analysis", False),
        "iab_categories": payload.get("iab_categories", False),
        "entity_detection": payload.get("entity_detection", False),
    }
    create_body = {k: v for k, v in create_body.items() if v is not None}
    create_resp = requests.post(transcription_url, headers=headers, json=create_body, timeout=config.get("timeout", 30))
    create_resp.raise_for_status()
    transcript_id = create_resp.json()["id"]

    poll_url = f"https://api.assemblyai.com/v2/transcript/{transcript_id}"
    params = {"audio_url": payload["audio_url"]}
    while True:
        resp = requests.get(poll_url, headers=headers, params=params, timeout=config.get("timeout", 30))
        resp.raise_for_status()
        data = resp.json()
        status = data.get("status")
        if status == "completed":
            if payload.get("timestamps", "word") == "segment":
                result = data.get("utterances") or data.get("segments") or []
            else:
                result = data.get("words") or []
            return result
        if status == "error":
            raise RuntimeError(data.get("error", "Transcription failed"))
